const contact = $input.first().json;
const request = $node['Webhook - Personalize'].json.body || $node['Webhook - Personalize'].json;

// Behavior-based segmentation
const engagement = {
  opens: contact.opens_30d || 0,
  clicks: contact.clicks_30d || 0,
  pageviews: contact.pageviews_30d || 0
};

// Determine engagement level
let engagementLevel = 'cold';
if (engagement.opens > 5 && engagement.clicks > 2) engagementLevel = 'hot';
else if (engagement.opens > 2 || engagement.clicks > 0) engagementLevel = 'warm';

// Determine content preferences from activity
const activities = contact.recent_activities || [];
const contentPreferences = [];
for (const act of activities) {
  if (act?.data?.content_type) contentPreferences.push(act.data.content_type);
  if (act?.data?.page_category) contentPreferences.push(act.data.page_category);
}
const topPreference = contentPreferences.length > 0 
  ? contentPreferences.sort((a, b) => contentPreferences.filter(v => v === b).length - contentPreferences.filter(v => v === a).length)[0]
  : 'general';

// Determine best CTA based on funnel stage
let cta = { text: 'Learn More', url: '/resources', style: 'soft' };
if (contact.lead_score >= 70) {
  cta = { text: 'Schedule a Demo', url: '/demo', style: 'hard' };
} else if (contact.lead_score >= 40) {
  cta = { text: 'See Case Studies', url: '/case-studies', style: 'medium' };
} else if (contact.lead_score >= 20) {
  cta = { text: 'Download Free Guide', url: '/resources/guide', style: 'soft' };
}

// Determine tone
let tone = 'professional';
if (contact.custom_fields?.industry === 'startup' || contact.custom_fields?.company_size === '1-10') {
  tone = 'casual';
} else if (contact.custom_fields?.industry === 'enterprise' || contact.custom_fields?.company_size === '500+') {
  tone = 'formal';
}

// Product recommendations based on behavior
const recommendations = [];
if (topPreference === 'seo' || contact.tags?.includes('seo')) {
  recommendations.push({ name: 'SEO Monitoring', description: 'Track your rankings daily' });
}
if (topPreference === 'marketing' || contact.tags?.includes('marketing')) {
  recommendations.push({ name: 'Marketing Automation', description: 'Automate your campaigns' });
}
if (topPreference === 'crm' || contact.tags?.includes('crm')) {
  recommendations.push({ name: 'CRM Integration', description: 'Sync all your contacts' });
}
if (recommendations.length === 0) {
  recommendations.push({ name: 'Getting Started', description: 'See what GreeVo can do for you' });
}

return [{
  json: {
    contact_id: contact.id,
    email: contact.email,
    first_name: contact.first_name,
    personalization: {
      engagement_level: engagementLevel,
      content_preference: topPreference,
      tone: tone,
      cta: cta,
      recommendations: recommendations,
      greeting: tone === 'casual' ? `Hey ${contact.first_name || 'there'}!` : 
                tone === 'formal' ? `Dear ${contact.first_name || 'Valued Customer'},` :
                `Hi ${contact.first_name || 'there'},`,
      show_social_proof: engagementLevel === 'cold',
      show_urgency: contact.lead_score >= 60,
      preferred_content_length: engagementLevel === 'hot' ? 'short' : 'medium'
    },
    template_data: {
      greeting: tone === 'casual' ? `Hey ${contact.first_name || 'there'}!` : `Hi ${contact.first_name || 'there'},`,
      cta_text: cta.text,
      cta_url: cta.url,
      recommendations: recommendations,
      engagement_level: engagementLevel
    }
  }
}];
